bool isLegalMfmaScaleF8f6f4Selector(uint32_t selector) {
  return (selector >= 240 && selector <= 248) || (selector >= 256 && selector <= 511);
}

bool isLegalMfmaF8f6f4Format(uint32_t format) { return format <= 4; }

